head.script:
scwin.screenId = "jlddst60205";

///////// 1. 변수 및 선언 영역 /////////

scwin.xmlHttp = undefined;

scwin.valMarket = undefined;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "c_when_16", fn: function(){ return ((dma_corpVO.get("marketType") ?? (() => { throw new Error("unresolved:" + "corpVO.marketType"); })()) === '1'); } }, { id: "c_when_18", fn: function(){ return ((dma_corpVO.get("marketType") ?? (() => { throw new Error("unresolved:" + "corpVO.marketType"); })()) === '2'); } }, { id: "c_when_20", fn: function(){ return ((dma_corpVO.get("marketType") ?? (() => { throw new Error("unresolved:" + "corpVO.marketType"); })()) === '6'); } }, { id: "c_when_35", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "isExaService" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("isExaService")) === 'Y'); } }, { id: "c_otherwise_50", fn: function(){ return (!((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "isExaService" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("isExaService")) === 'Y'))); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_isurcd", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("isurcd")))); } },
        { childId: "ipt_isurcd2", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("isurcd")))); } },
        { childId: "ipt_isurCd", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("isurcd")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.initComNmSetting
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.initComNmSetting = async function () {
    /* sdd-asis-lifecycle:begin initComNmSetting — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const comnm = scwin.getRecentCompanyFromCookie();
    if (comnm != null && comnm !== "") {
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("comAbbrv", comnm);
        await scwin.fnSearchCorpBasicInfo();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.util.getComponent("tabContents").setStyle("display", "none");
        console.error("[sdd] 미실현 동작: set_label (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_label — {target}.setLabel({args}) */
        await scwin.fnSearch();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst60205.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @description tab-contents 을(를) 보이기를 바꾼다 · 표시 문구를 바꾼다 외
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst60205.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

