 * @method
 * @name scwin.fnGetCookie
 * @author Inswave
 * @date 2026. 09. 29
 * @param keyname
 * @returns
 * @hidden N
*/
scwin.fnGetCookie = function (keyname) { const v = $c.util.getSessionStorage(keyname); return (v === undefined || v === null) ? '' : v; };


