/**
 * @method
 * @name scwin.fnSearchCorpBasicInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpBasicInfo = async function () {
    /* sdd-asis-lifecycle:begin fnSearchCorpBasicInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let cd_or_nm = ($c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").get("comAbbrv") || '');
    if (cd_or_nm === "") {
        await $c.win.alert("회사명 또는 종목코드를 입력해 주세요.");
        return;
    }
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", "");
    cd_or_nm = cd_or_nm.replace(/\&/gi, '#amp#');
    cd_or_nm = cd_or_nm.replace(/\+/gi, '#plus#');
    await scwin.tx_fnSearchCorpBasicInfo_rawxhr();
    /* sdd-asis-lifecycle:end */
};


